const fmt=(d?:string)=>d?new Date(d.length===10?d+'T12:00:00Z':d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dubai'}):'Not set';
const chip=(s:string)=>'pill '+(/High|Failed|Expired|Rejected/.test(s)?'red':/Medium|Pending|requested|review|Draft|Partial|Awaiting|submitted/.test(s)?'amber':/Low/.test(s)?'yellow':/Verified|Closed|Issued|Approved|Processed|Completed|Confirmed/.test(s)?'green':'grey');
