let currentPrincipal:R|null=null;
export function setCurrentPrincipal(p:R|null){currentPrincipal=p;}
async function api(path:string,data?:any):Promise<any>{
  if(!currentPrincipal) throw Error('Not signed in.');
  if(path==='state') return getState(currentPrincipal);
  if(path==='bootstrap') return seedReferenceData(currentPrincipal);
  if(path==='session') throw Error('Demonstration role switching is not part of this build — sign in with the real account you want to use.');
  return apiRouter(currentPrincipal,path,data);
}
function Empty({text='No records yet',children}:{text?:string,children?:React.ReactNode}){return <div className="empty"><ClipboardCheck size={32}/><h3>{text}</h3>{children}</div>}
