function Table({headers,rows,onRow}:{headers:string[],rows:any[][],onRow?:(n:number)=>void}){return <div className="table-scroll"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i} className={onRow?'clickable':''} onClick={()=>onRow?.(i)}>{r.map((v,j)=><td key={j}>{v}</td>)}</tr>)}</tbody></table>{!rows.length&&<Empty/>}</div>}
