 const load=async()=>{try{const s=await api('state');setState(s);setError('');if(!['group','gcbdo'].includes(s.profile.role)&&view==='overview')setView('entities');}catch(e:any){setError(e.message);}};
 useEffect(()=>{(async()=>{try{await api('bootstrap',{});}catch{/* best-effort; only the group admin can seed, and only once */}try{await load();const p=new URLSearchParams(location.search);if(p.get('view'))setView(p.get('view')!);if(p.get('audit'))setAudit(p.get('audit')!);}catch(e:any){setError(e.message);}})();},[]);
 const run=async(fn:()=>Promise<any>,message='Saved',close=true)=>{setBusy(true);try{const result=await fn();if(message)toast.success(message);await load();if(close)setModal(null);return result;}catch(e:any){toast.error(e.message,{duration:7000});return null;}finally{setBusy(false);}};
 const post=(path:string,data:any,message?:string)=>run(()=>api(path,data),message);const assessAudit=(id:string)=>run(async()=>{const job=await api('jobs',{audit:id});return api('jobs/'+job.id+'/process',{});},'Assessment saved for human review');
 const records:R[]=state?.records||[],p=state?.profile||{},isGroup=p.role==='group',reviewer=['group','independent'].includes(p.role),isCEO=p.role==='ceo',canEvidence=['group','mr','owner','auditor','independent'].includes(p.role);
