 const entityTable=()=> <Table headers={['Entity','Checklist','Audit activity','Documentary coverage','Highest unresolved risk','']} rows={entities.filter(matches).map(e=>{const fs=findings.filter(f=>f.entity===e.id&&!['Rejected','Verified closed'].includes(f.status));const ins=instances.filter(i=>i.entity===e.id);return [<div className="entity-cell">{logo(e)}<b>{e.name}</b></div>,`${of('control').filter(c=>c.entity===e.id).length} controls`,`${audits.filter(a=>a.entity===e.id).length} audits`,ins.length?`${ins.filter(i=>i.result!=='Unassessed').length} / ${ins.length} reviewed`:'Not assessed',<Badge value={['High','Medium','Low'].find(x=>fs.some(f=>f.risk===x))||'Unassessed'}/>,<button className="link" onClick={()=>{setEntity(e.id);setView('audits');setAudit('');}}>Open <ChevronRight size={16}/></button>];})}/>;
